// ─────────────────────────────────────────────────────────
// L2 ACCESS — single source of truth for summary lookup
// ─────────────────────────────────────────────────────────
// Priority: real L2 in importedData → mock (if demo profile + mock not disabled).
// Real data takes over as soon as the user connects any adapter.

function isMockAllowed() {
  if (localStorage.getItem('wearables-mock-off') === '1') return false;
  // Show mock only when no real connection exists — keeps the dashboard lively
  // during onboarding / demo flows without shadowing real data.
  const real = state.importedData?.wearableSummary as SummaryOperations | null | undefined;
  if (real && real.sources && Object.keys(real.sources).length > 0) return false;
  return true;
}

function getWearableSummary(): SummaryOperations | null {
  const real = state.importedData?.wearableSummary as SummaryOperations | null | undefined;
  if (real && real.sources && Object.keys(real.sources).length > 0) return real;
  if (isMockAllowed()) return MOCK_SUMMARY;
  return null;
}

// ─────────────────────────────────────────────────────────
// FORMATTERS
// ─────────────────────────────────────────────────────────

function formatAgo(ts: number | null | undefined) {
  if (!ts) return 'never';
  const mins = Math.max(0, Math.round((Date.now() - ts) / 60000));
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.round(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  const days = Math.round(hrs / 24);
  return `${days}d ago`;
}

// Semantic delta colour: worse-direction → red, better-direction → green, ~flat → neutral.
// Returns 'delta-flat' for zero/missing baseline so we don't paint NaN% red/green.
function deltaClassFor(latest: number | null | undefined, baseline: number | null | undefined, worseWhen: unknown) {
  if (!baseline || !isFinite(baseline)) return 'delta-flat';
  const pct = (((latest as number) - baseline) / baseline) * 100;
  if (Math.abs(pct) < 3) return 'delta-flat';
  const isDown = pct < 0;
  const worse = (isDown && worseWhen === 'down') || (!isDown && worseWhen === 'up');
  if (worseWhen === 'either') return 'delta-flat';
  return worse ? 'delta-bad' : 'delta-good';
}

// Delta-style metrics (e.g. body_temp_delta — Oura/Whoop temperature deviation
// from the user's nightly norm) already encode a Δ; their baseline naturally
// hovers near zero, so percentages blow up (baseline=-0.05, latest=0.5 →
// "↓ 1100%"). For these we render the absolute change in unit instead.
function isDeltaStyleMetric(canon: CanonicalMetric | null | undefined) {
  return canon?.sub === 'Δ';
}

function formatDelta(latest: number | null | undefined, baseline: number | null | undefined, metricId: string, canon: CanonicalMetric) {
  // Zero baseline happens when the metric is 0 across the period (e.g. activity
  // score on a ring that wasn't worn) — suppress the delta entirely rather than
  // rendering "→ —" which reads as "we measured something."
  if (!baseline || !isFinite(baseline)) return '';
  // Steps fluctuates wildly intraday (132 at 9 AM vs 8000 at 9 PM); a baseline
  // delta against an in-progress count is dishonest. Hide the arrow on steps.
  if (metricId === 'steps') return '';
  // For "lower is better" metrics, a current value of 0 against a non-zero
  // baseline produces a noisy "↓ 100%" that grabs attention without insight
  // (e.g. zero stress minutes today reads alarming when it's actually good).
  // Suppress when current is 0 and baseline is non-trivial.
  if (latest === 0 && Math.abs(baseline) > 0.5) return '';
  if (latest == null || !isFinite(latest)) return '';
  if (isDeltaStyleMetric(canon)) {
    const diff = latest - baseline;
    const arrow = diff > 0.005 ? '↑' : diff < -0.005 ? '↓' : '→';
    const unit = canon?.unit ? canon.unit : '';
    return `${arrow} ${Math.abs(diff).toFixed(2)}${unit}`;
  }
  const pct = (((latest as number) - baseline) / baseline) * 100;
  const arrow = pct > 0.5 ? '↑' : pct < -0.5 ? '↓' : '→';
  return `${arrow} ${Math.abs(pct).toFixed(0)}%`;
}

function trendLabel(t: unknown) {
  if (t === 'declining') return 'declining 30d';
  if (t === 'rising')    return 'rising 30d';
  if (t === 'improving') return 'improving 30d';
  return 'flat 30d';
}

function trendClassFor(trend: unknown, worseWhen: unknown) {
  // 'declining' and 'rising' are directional — paint them the semantic colour
  // based on which direction is worse for THIS metric.
  if (trend === 'improving') return 'wearable-trend-improving';
  if (trend === 'flat')      return 'wearable-trend-flat';
  const isBad = (trend === 'declining' && worseWhen === 'down') || (trend === 'rising' && worseWhen === 'up');
  return isBad ? 'wearable-trend-bad' : 'wearable-trend-good';
}

// ─────────────────────────────────────────────────────────
// SPARKLINE
// ─────────────────────────────────────────────────────────

function sparklineSVG(series: number[] | null | undefined, baseline: number, worseWhen: unknown) {
  if (!series || series.length === 0) return '';
  const VW = 100, VH = 30, pad = 2;
  const all = series.concat([baseline]);
  const min = Math.min(...all), max = Math.max(...all);
  const range = Math.max(max - min, 1e-6);
  const xStep = (VW - pad * 2) / Math.max(series.length - 1, 1);
  const yFor = (v: number) => VH - pad - ((v - min) / range) * (VH - pad * 2);
  const pts = series.map((v, i) => `${(pad + i * xStep).toFixed(1)},${yFor(v).toFixed(1)}`).join(' ');
  const lastX = (pad + (series.length - 1) * xStep).toFixed(1);
  const lastY = yFor(series[series.length - 1]!).toFixed(1);
  const baselineY = yFor(baseline).toFixed(1);
  const last = series[series.length - 1]!;
  const deltaPct = (baseline && isFinite(baseline)) ? Math.abs((last - baseline) / baseline) : 0;
  let toneClass = 'spark-neutral';
  if (deltaPct >= 0.03 && worseWhen !== 'either') {
    const endsBelow = last < baseline;
    const bad = (endsBelow && worseWhen === 'down') || (!endsBelow && worseWhen === 'up');
    toneClass = bad ? 'spark-bad' : 'spark-good';
  }
  return renderWearableSparklinePresentation({
    toneClass: `${toneClass}`, width: `${VW}`, height: `${VH}`,
    baselineStartY: `${baselineY}`, baselineWidth: `${VW}`, baselineEndY: `${baselineY}`,
    points: `${pts}`, lastX: `${lastX}`, lastY: `${lastY}`,
  });
}

// ─────────────────────────────────────────────────────────
// RENDER
// ─────────────────────────────────────────────────────────

// Empty-state card for manual-capable metrics that have no data yet.
// Tap / click → opens an inline entry form in-place (see _openManualLogForm).
// For bp_systolic the form prompts for both systolic + diastolic (and
// optional pulse) on one card; bp_diastolic and rhr are folded into that
// same card when BP is empty, so the user sees ONE "BP" affordance rather
// than three.
function renderEmptyManualCard(metricId: string, canon: CanonicalMetric, opts: CardOptions = {}) {
  const subLabel = canon.sub ? wearableEmptyText(canon.sub) : null;
  const label = metricId === 'bp_systolic' ? 'Blood pressure' : canon.label;
  const interactive = opts.interactive !== false;
  const actionAttrs = interactive
    ? `${wearableActionAttrs('open-manual-log', { metric: metricId })} role="button" tabindex="0"`
    : 'aria-disabled="true"';
  const metric = wearableEmptyText(metricId);
  const accessibleLabel = wearableEmptyText(label.toLowerCase());
  const displayLabel = wearableEmptyText(label);
  qualifyWearableEmptyAction(metric, interactive, actionAttrs);
  return renderWearableEmptyCardPresentation({metric, interactive, accessibleLabel, label: displayLabel,
    sub: metricId === 'bp_systolic' ? null : subLabel});
}

function formatStalenessDate(date: string | null | undefined) {
  if (!date) return '';
  const d = new Date(`${date}T00:00:00`);
  if (Number.isNaN(d.getTime())) return shortDate(date);
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

function renderCard(metricId: string, canon: CanonicalMetric, metric: MetricOperations, showSourceBadge: unknown, sourceMaxDate: string | undefined, opts: CardOptions = {}) {
  const pairedMetric = opts.pairedMetric || null;
  const interactive = opts.interactive !== false;
  // Paired BP card: relabel "BP sys" → "Blood pressure", swap latest/baseline
  // for the "sys/dia" pair string. Trend/sparkline/delta stay sys-based —
  // sys is the more clinically actionable of the two and adding a dual-line
  // sparkline would crowd the card.
  const isBPCard = metricId === 'bp_systolic' && pairedMetric;
  const cardLabel = isBPCard ? 'Blood pressure' : canon.label;
  const cardSub = isBPCard ? null : canon.sub;
  const deltaCls = deltaClassFor(metric.latest, metric.baseline, canon.worseWhen);
  const deltaText = formatDelta(metric.latest, metric.baseline, metricId, canon);
  // Space-prefix the sub so screen readers hear "HRV RMSSD" not "HRVRMSSD".
  // Visual spacing is still margin-left via .wearable-metric-sub CSS.
  const subLabel = cardSub ? renderWearableStripPresentation("WearableMetricCard", "subLabel", {
      escapedSubLabel: () => (escapeHTML(cardSub))
    }) : '';
  // Units starting with "/" (e.g. "/5" for resilience level) read tighter
  // without a separator between value and unit — render "1/5", not "1 /5".
  const displayUnit = wearableDisplayUnit(metricId, canon.unit || '', state.unitSystem);
  const formatDisplayValue = (value: number | null | undefined) => formatWearableMetricValue(
    metricId,
    value,
    canon.unit || '',
    state.unitSystem,
  );
  const unitTight = displayUnit.startsWith('/');
  const unitLabel = displayUnit ? renderWearableStripPresentation("WearableMetricCard", "unit", {
      tightUnitClass: () => (unitTight ? ' wearable-unit-tight' : ''),
      escapedUnit: () => (escapeHTML(displayUnit))
    }) : '';
  const baselineUnit = displayUnit
    ? (unitTight ? escapeHTML(displayUnit) : ' ' + escapeHTML(displayUnit))
    : '';
  const trendCls = trendClassFor(metric.trend30d, canon.worseWhen);
  // Per-metric staleness: when this metric's latest sample is older than
  // the freshest sample on its source (typically because the underlying
  // endpoint has a processing delay — e.g. Oura's /usercollection/sleep
  // populates HRV/RHR hours after /daily_sleep is up), surface an "as of
  // {date}" hint so the value reads honestly rather than "fresh."
  const isStale = metric.latestDate && sourceMaxDate && metric.latestDate < sourceMaxDate;
  const stalenessHint = isStale
    ? renderWearableStripPresentation("WearableMetricCard", "staleness", {
      latestDate: () => (escapeHTML(metric.latestDate)),
      formattedDate: () => (escapeHTML(formatStalenessDate(metric.latestDate)))
    })
    : '';
  const adapter = adapterById(metric.primarySource);
  // Source badge is interactive when >1 wearable is connected — click it to
  // open a small picker that overrides the primary source for this metric.
  // Without the override, the summary picker auto-picks by most-recent
  // non-null value, which can feel arbitrary when two sources report similar
  // freshness. The override is per-metric, persisted in importedData.
  const sourceBadge = (interactive && showSourceBadge && adapter)
    ? renderWearableStripPresentation("WearableMetricCard", "sourceBadge", {
      sourceActionAttributes: () => (wearableActionAttrs('choose-source', { metric: metricId })),
      sourceName: () => (escapeHTML(adapter.displayName))
    }) : '';
  // Build a meaningful aria-label: value + unit + trend direction + metric
  // name so screen readers can read the card at a glance without entering it.
  const sysRead = formatDisplayValue(metric.latest);
  const diaRead = isBPCard ? formatDisplayValue(pairedMetric.latest) : null;
  const valueRead = isBPCard ? `${sysRead}/${diaRead || '—'}` : sysRead;
  const formatBaselineValue = (value: number | null | undefined) => metricId === 'weight'
    ? formatDisplayValue(value)
    : String(value ?? '—');
  const baselineRead = isBPCard
    ? `${formatBaselineValue(metric.baseline)}/${formatBaselineValue(pairedMetric.baseline)}`
    : formatBaselineValue(metric.baseline);
  const trendRead = trendLabel(metric.trend30d);
  // Glyph subs (🌙/☀️) don't speak well; map to words for screen readers.
  // English word subs (e.g. "SDNN") read fine as-is. Some metrics override
  // the entire spoken label via canon.ariaLabel ("BP" → "Blood pressure …").
  const subRead = canon.sub === '🌙' ? 'overnight'
               : canon.sub === '☀️' ? 'daytime'
               : canon.sub;
  const canonRead = isBPCard
    ? 'Blood pressure'
    : (canon.ariaLabel
        ? canon.ariaLabel
        : (subRead ? `${canon.label} ${subRead}` : canon.label));
  const deltaRead = deltaText
    ? `${deltaText.replace('↑', 'up').replace('↓', 'down').replace('→', 'flat at')} vs baseline, `
    : '';
  const ariaLabel = `${canonRead} ${valueRead}${displayUnit ? ' ' + displayUnit : ''}, ${deltaRead}${trendRead} — open detail`;
  const actionAttrs = interactive
    ? ` ${wearableActionAttrs('open-detail', { metric: metricId })} role="button" tabindex="0"`
    : '';
  return renderWearableStripPresentation("WearableMetricCard", "card", {
      actionAttributes: () => (actionAttrs),
      accessibleLabel: () => (escapeAttr(ariaLabel)),
      label: () => (escapeHTML(cardLabel)),
      subLabel: () => (subLabel),
      optionalDelta: () => (deltaText ? renderWearableStripPresentation("WearableMetricCard", "delta", {
      deltaClass: () => (deltaCls),
      deltaText: () => (deltaText)
    }) : ''),
      value: () => (valueRead),
      unit: () => (unitLabel),
      baselineValue: () => (escapeHTML(baselineRead)),
      baselineUnit: () => (baselineUnit),
      staleness: () => (stalenessHint),
      sparkline: () => (sparklineSVG(metric.weekly, metric.baseline, canon.worseWhen)),
      trendClass: () => (trendCls),
      trendLabel: () => (trendLabel(metric.trend30d)),
      sourceBadge: () => (sourceBadge)
    });
}

// Compact "connect a wearable" stub for users who have lab data but no
// connected source. Without this the wearables feature has no persistent
// dashboard surface — users who skipped the welcome hero, never opened
// chat onboarding, and dismissed the demo cards have no way of
// discovering it post-import. Dismissible (per-profile) so it doesn't
// nag users who genuinely don't want a wearable.
function renderWearableStripStub() {
  const dismissed = localStorage.getItem(`labcharts-wearable-stub-dismissed-${state.currentProfile}`) === '1';
  if (dismissed) return '';
  const connect = `${wearableActionAttrs('open-settings-wearables')}`;
  const dismiss = `${wearableActionAttrs('dismiss-stub')}`;
  return renderWearableStripStubPresentation(projectWearableStripStubActions(connect,dismiss));
}

export function dismissWearableStub() {
  localStorage.setItem(`labcharts-wearable-stub-dismissed-${state.currentProfile}`, '1');
  navigateWearables('dashboard');
}

export function renderWearableStrip() {
  installWearableDelegates();
  const wearablesHidden = isWearableStripHidden();
  let summary = getWearableSummary();
  // Wearables-off mode: drop the demo summary (no mock vendor cards) so
  // we only render real data the user actually logged.
  if (wearablesHidden && summary === MOCK_SUMMARY) summary = null;
  if (!summary) {
    // No real summary AND mock is suppressed (or off). Surface the stub
    // so users who skipped the welcome flow still discover the feature —
    // unless wearables are explicitly off, in which case the user has
    // opted out of vendor integrations entirely.
    if (wearablesHidden) return '';
    return renderWearableStripStub();
  }
  // Sort by ADAPTERS registry order (Oura first, Apple Health last) instead
  // of summary.sources insertion order — that way the strip header reads
  // "Oura + Fitbit + Apple Health" regardless of which one the user
  // connected first.
  const adapterOrderIndex = (sid: string) => {
    const idx = ADAPTERS.findIndex(a => a.id === sid);
    return idx === -1 ? 999 : idx;
  };
  let sourceIds = Object.keys(summary.sources || {})
    .sort((a, b) => adapterOrderIndex(a) - adapterOrderIndex(b));
  // Wearables-off mode: keep only the manual pseudo-source. Manual weight,
  // BP, and pulse cards still render — wearable vendor cards (Oura, etc.)
  // drop out.
  if (wearablesHidden) sourceIds = sourceIds.filter(s => s === 'manual');
  // In wearables-off mode, fall through to the render path even if the user
  // has no 'manual' source yet — the MANUAL_EMPTY_METRICS placeholders below
  // give them a way to discover hand-logging weight / BP / RHR. Synthesize
  // a virtual 'manual' source id; the chrome that uses summary.sources[s]
  // (last-synced label, sync button, demo pill) is hidden in manualOnly mode
  // anyway, and null-safe access protects what's left.
  if (wearablesHidden && sourceIds.length === 0) sourceIds = ['manual'];
  if (sourceIds.length === 0) return renderWearableStripStub();
  if (!summary.metrics || Object.keys(summary.metrics).length === 0) {
    if (!wearablesHidden) return renderWearableStripStub();
    // else: wearables-off + no metrics — keep going so MANUAL_EMPTY_METRICS render.
  }

  const collapsed = localStorage.getItem('wearables-strip-collapsed') === '1';
  // Connected vendors that haven't returned any rows yet (e.g. Polar account
  // with no recent device sync) shouldn't headline the strip — they make
  // "Wearables: Oura + Polar · 15d" read like Polar contributed half the data.
  // Surface them in the footer instead.
  const sourcesWithData = sourceIds.filter(s => (summary.sources?.[s]?.coverageDays || 0) > 0);
  // 'manual' is user-authored data — it's not a device that can be "waiting
  // on a device sync", so exclude it from the waiting footer note even when
  // coverageDays is zero (e.g. user touched the manual adapter without
  // saving anything yet).
  const sourcesWaiting  = sourceIds.filter(s => s !== 'manual' && (summary.sources?.[s]?.coverageDays || 0) === 0);
  const headerSourceIds = sourcesWithData.length ? sourcesWithData : sourceIds;
  const baseMetricOrder = metricsForSources(headerSourceIds);
  const showSourceBadges = headerSourceIds.length > 1;

  // Merge populated + empty manual cards into one ordered list so the user
  // can reorder across all of them, not just per-category. Empty cards for
  // weight/bp_systolic/rhr fill in wherever they're not already present.
  const MANUAL_EMPTY_METRICS = ['weight', 'bp_systolic', 'rhr'];
  // Daytime companions live in the detail modal as sub-stats, not as their
  // own cards — keeps the strip calm at 6-8 cards instead of 10.
  const STRIP_HIDDEN_METRICS = new Set(['hrv_day', 'hr_day']);
  // BP renders as one paired card (sys/dia). When systolic is present we
  // suppress diastolic's standalone card and fold it into sys's render. If
  // somehow only dia exists (no sys), let dia surface on its own so the data
  // isn't invisible.
  const hasSys = !!summary.metrics?.bp_systolic;
  const displayOrder: DisplayItem[] = [];
  const seenDisplay = new Set();
  for (const id of baseMetricOrder) {
    if (STRIP_HIDDEN_METRICS.has(id)) continue;
    if (id === 'bp_diastolic' && hasSys) continue;
    const m = summary.metrics?.[id];
    if (!m) continue;
    // Wearables-off mode: only manual-sourced cards survive. Vendor metrics
    // (HRV, sleep score, etc.) hide; the stored data stays untouched so
    // flipping the toggle back on restores them instantly.
    if (wearablesHidden && m.primarySource !== 'manual') continue;
    displayOrder.push({ id, empty: false });
    seenDisplay.add(id);
  }
  for (const id of MANUAL_EMPTY_METRICS) {
    if (!seenDisplay.has(id) && canonicalMetric(id)) {
      displayOrder.push({ id, empty: true }); seenDisplay.add(id);
    }
  }
  // Apply the user's saved card order: items present in the saved order
  // render first (in that order), anything new appends at the end. New
  // metrics added in a future version auto-surface without a migration.
  const savedOrder = Array.isArray(state.importedData?.wearableCardOrder)
    ? state.importedData.wearableCardOrder : null;
  const finalOrder = savedOrder && savedOrder.length
    ? (() => {
        const byId = new Map(displayOrder.map(d => [d.id, d]));
        const out: DisplayItem[] = [];
        for (const id of savedOrder) {
          const item = byId.get(id);
          if (item) { out.push(item); byId.delete(id); }
        }
        for (const d of displayOrder) if (byId.has(d.id)) out.push(d);
        return out;
      })()
    : displayOrder;

  const reorderMode = !!state._wearableReorderMode;

  // Per-source freshest latestDate across all metrics — lets the per-card
  // renderer flag metrics whose latest sample is older than the source's
  // own freshest reading (e.g. HRV from Oura's /sleep lags daily_sleep by
  // hours-to-days while the night's session finishes processing).
  const sourceMaxDate: Record<string, string> = {};
  for (const m of Object.values(summary.metrics || {})) {
    const src = m?.primarySource;
    const d = m?.latestDate;
    if (!src || !d) continue;
    if (!sourceMaxDate[src] || d > sourceMaxDate[src]!) sourceMaxDate[src] = d;
  }

  // Header meta: most recent sync across connected sources + a short coverage label.
  const lastSyncAt = Math.max(0, ...sourceIds.map(s => summary.sources?.[s]?.lastSyncAt || 0));
  const coverageDays = Math.max(0, ...headerSourceIds.map(s => summary.sources?.[s]?.coverageDays || 0));
  const sourceLabel = headerSourceIds.map(id => adapterById(id)?.displayName || id).join(' + ');
  const coverageLabel = coverageDays > 0 ? ` · ${coverageDays}d` : '';
  const waitingLabel = sourcesWaiting
    .map(id => adapterById(id)?.displayName || id)
    .join(', ');

  const isMock = localStorage.getItem('wearables-mock-off') !== '1' &&
    /* mock flag: summary === MOCK_SUMMARY — avoid import cycle by comparing a sentinel */
    summary === MOCK_SUMMARY;
  // Demo profiles loaded via loadDemoData (Demo Alex / Demo Sarah) carry
  // a `demo` tag. Sarah's data lands in real summary slots because it
  // loads from data/demo-female.json — without this branch she'd render
  // identical to a real wearables strip, hiding the "this is a sample"
  // signal that Alex (whose summary === MOCK_SUMMARY) gets for free.
  const isDemoProfile = (() => {
    try {
      const profilesRaw = localStorage.getItem('labcharts-profiles');
      if (!profilesRaw) return false;
      const profiles = JSON.parse(profilesRaw) as ProfileCacheReader;
      const active = profiles.find(p => p.id === state.currentProfile);
      return Array.isArray(active?.tags) && active.tags.includes('demo');
    } catch (_) { return false; }
  })();
  const showDemoPill = isMock || isDemoProfile;

  // Originally a footer caveat listed SDNN / pNN50 / HF/LF as "deep HRV"
  // metrics that need a chest strap. Real users found that confusing —
  // they don't know what those acronyms mean and the note made the strip
  // feel like it was apologising for itself. Removed in v1.28.2; the
  // detail-modal HRV stats and AI context label HRV as "overnight" /
  // "daytime" without jargon, which is clearer.
  const hrvNote = '';
  const waitingNote = waitingLabel
    ? `${waitingLabel} connected — waiting on first device sync.`
    : '';

  // When wearables are off the strip is purely manual entries — drop the
  // "Wearables: Oura · 15d" header, the sync button (nothing remote to
  // sync), and the demo pill / waiting note.
  const manualOnly = wearablesHidden;
  const titleHTML = manualOnly
    ? renderWearableStripPresentation("WearableStripHeader", "manualTitle", {})
    : renderWearableStripPresentation("WearableStripHeader", "sourceTitle", {
      sourceNames: () => (escapeHTML(sourceLabel)),
      coverage: () => (coverageLabel)
    });
  const hasStaleSource = !manualOnly && sourceIds.some(s => s !== 'manual' && Date.now() - (summary.sources?.[s]?.lastSyncAt || 0) >= 12 * 60 * 60 * 1000);
  const lastSyncHTML = manualOnly ? '' : renderWearableStripPresentation("WearableStripHeader", "lastSync", {
      lastSyncAge: () => (formatAgo(lastSyncAt))
    });
  const syncBtnHTML = manualOnly || !hasStaleSource ? '' : renderWearableStripPresentation("WearableStripHeader", "syncButton", {
      syncActionAttributes: () => (wearableActionAttrs('sync-now'))
    });
  const ariaLabel = manualOnly
    ? (collapsed ? 'Expand biometrics strip' : 'Collapse biometrics strip')
    : (collapsed ? 'Expand wearables strip' : 'Collapse wearables strip');

  // axe nested-interactive: parent is mouse-clickable but keyboard toggle
  // lives on the chevron button below. Nested buttons carry their own
  // delegated actions, so the document handler only runs the closest action.
  let html = renderWearableStripPresentation("WearableStripHeader", "header", {
      toggleHeaderAttributes: () => (wearableActionAttrs('toggle-strip')),
      title: () => (titleHTML),
      optionalDemoPill: () => (!manualOnly && showDemoPill ? renderWearableStripPresentation("WearableStripHeader", "demoPill", {
      settingsActionAttributes: () => (wearableActionAttrs('open-settings-wearables'))
    }) : ''),
      optionalReorderHint: () => (reorderMode ? renderWearableStripPresentation("WearableStripHeader", "reorderHint", {}) : ''),
      lastSync: () => (lastSyncHTML),
      syncButton: () => (syncBtnHTML),
      reorderActiveClass: () => (reorderMode ? ' active' : ''),
      reorderAccessibleLabel: () => (reorderMode ? 'Done reordering' : 'Reorder cards'),
      reorderTitle: () => (reorderMode ? 'Done reordering' : 'Reorder cards'),
      reorderActionAttributes: () => (wearableActionAttrs('toggle-reorder')),
      reorderText: () => (reorderMode ? 'Done' : '⇄ Reorder'),
      collapseClass: () => (collapsed ? ' collapsed' : ''),
      expanded: () => (!collapsed),
      collapseAccessibleLabel: () => (ariaLabel),
      collapseActionAttributes: () => (wearableActionAttrs('toggle-strip')),
      gridHiddenClass: () => (collapsed ? ' hidden' : ''),
      gridReorderClass: () => (reorderMode ? ' wearable-card-grid-reorder' : '')
    });

  // Unified render loop — both populated and empty cards flow in the
  // user-defined order (finalOrder). In reorder mode each card gains ◀ ▶
  // arrow handles and detail-modal clicks are suppressed.

  for (let i = 0; i < finalOrder.length; i++) {
    const { id: metricId, empty } = finalOrder[i]!;
    const canon = canonicalMetric(metricId);
    if (!canon) continue;
    let cardHtml: string;
    if (empty) {
      cardHtml = renderEmptyManualCard(metricId, canon, { interactive: !reorderMode });
    } else {
      const metric = (summary.metrics as NonNullable<SummaryOperations['metrics']>)[metricId];
      if (!metric) continue;
      // Source badge appears on every populated card whenever ≥2 wearables
      // are connected — users need to see at-a-glance which source backs each
      // metric, not just the strip header. The badge stays clickable so they
      // can swap source per metric (auto-picker fallback when only one source
      // declares it). Single-source connections still hide the badge to avoid
      // redundancy with the header.
      // BP card: pull the dia partner so renderCard can format "120/80".
      const pairedMetric = (metricId === 'bp_systolic') ? summary.metrics?.bp_diastolic : null;
      cardHtml = renderCard(metricId, canon, metric, showSourceBadges, sourceMaxDate[metric.primarySource], { pairedMetric, interactive: !reorderMode });
    }
    if (reorderMode) {
      const canLeft = i > 0;
      const canRight = i < finalOrder.length - 1;
      cardHtml = renderWearableStripPresentation("WearableStripBody", "reorderCard", {
      metricAttribute: () => (escapeHTML(metricId)),
      card: () => (cardHtml),
      leftAccessibleLabel: () => (escapeHTML(canon.label)),
      leftDisabled: () => (canLeft ? '' : 'disabled'),
      leftActionAttributes: () => (wearableActionAttrs('move-card', { metric: metricId, delta: -1 })),
      rightAccessibleLabel: () => (escapeHTML(canon.label)),
      rightDisabled: () => (canRight ? '' : 'disabled'),
      rightActionAttributes: () => (wearableActionAttrs('move-card', { metric: metricId, delta: 1 }))
    });
    }
    html += cardHtml;
  }

  html += renderWearableStripPresentation("WearableStripBody", "gridEnd", {});
  if (waitingNote || hrvNote) {
    html += renderWearableStripPresentation("WearableStripBody", "footerStart", {
      hiddenClass: () => (collapsed ? ' hidden' : '')
    });
    if (waitingNote) html += renderWearableStripPresentation("WearableStripBody", "waitingNote", {
      waitingNote: () => (escapeHTML(waitingNote))
    });
    if (hrvNote)     html += renderWearableStripPresentation("WearableStripBody", "hrvNote", {
      hrvNote: () => (escapeHTML(hrvNote))
    });
    html += renderWearableStripPresentation("WearableStripBody", "footerEnd", {});
  }
  html += renderWearableStripPresentation("WearableStripBody", "stripEnd", {});
  return html;
}
installWearableDelegates();

configureWearablesModuleBridge({
  openWearableDetail,
  syncWearableNow,
  openManualLogForm,
  _uninstallWearableModalFocusTrap,
});

wearables-detail-modal.ts:
import { getErrorMessage } from './caught-error.js';
import { escapeHTML, showNotification } from './utils.js';
import { actionAttributes } from './action-attributes.js';
import { state } from './state.js';
import {
  adapterById,
  canonicalMetric,
  CUMULATIVE_METRICS,
  isMetricValueMeaningful,
  isoDay,
} from './wearable-adapters.js';
import { getActiveProfileId } from './profile.js';
import { getDailyRange } from './wearables-store.js';
import { MANUAL_METRICS } from './wearables-manual.js';
import { getChartColors } from './theme.js';
import { ensureChartJs, formatChartTickValue, isChartDateAdapterReady } from './charts.js';
import {
  formatWearableMetricValue,
  shortDate,
  wearableDisplayUnit,
} from './wearables-formatters.js';
import { renderBloodPressureChart } from './wearables-bp-detail-chart.js';
import { openModalOverlay } from './modal-lifecycle.js';
import {
  closeWearableDetailModalRuntime,
  createWearableDetailChartRuntime,
  hasWearableDetailChartRuntime,
  rememberWearableDetailModalTriggerRuntime,
} from './wearables-detail-runtime.js';
import {
  closeManualAddFromDetail,
  configureWearableManualDetailDeps,
  deleteManualEntryFromDetail,
  openManualAddFromDetail,
  saveManualEntryFromDetail,
} from './wearables-manual-detail.js';

import type { CanonicalWearableMetric } from './wearable-adapters.js';
import type { StoredWearableRow } from './wearable-storage-types.js';
import type { WearableMetricSummary } from './wearables-summary-model.js';
import { renderWearableDetailPresentation } from './wearable-detail-presentation.js';

interface WearableSeriesPoint { date: StoredWearableRow['date']; v: number }
interface ManualDetailPoint extends Pick<StoredWearableRow, 'date'> {
  v: unknown; pairedV: unknown; tags: unknown; note: unknown;
}
export interface WearableDetailOptions { fromRangeToggle?: unknown }
// Private consumed operations describe the original unchecked summary readers;
// restored storage is not normalized or validated by this module.
type DetailMetricReader = WearableMetricSummary;
interface DetailHtmlOptions {
  allZeroActivity?: unknown; rangeKey?: unknown; rangeStartDate?: unknown;
  pairedMetric?: DetailMetricReader | null | undefined;
  pairedSeries?: readonly WearableSeriesPoint[];
  pairedMetricId?: string | null; chartSampleCount?: number;
  manualChartSampleCount?: unknown;
}
interface WearableChartDataset {
  type?: 'scatter'; label: string; data: Array<{x: string | undefined; y: unknown}>;
  _kind: 'primary' | 'baseline' | 'manual'; borderColor: string; backgroundColor: string;
  borderWidth?: number; borderDash?: number[]; pointRadius: number | number[];
  pointBackgroundColor?: string[]; pointBorderColor?: string[];
  pointHoverRadius: number | number[]; tension?: number; spanGaps?: boolean; showLine?: boolean;
  segment?: { borderDash: (ctx: {p1DataIndex: number}) => number[] | undefined;
    borderColor: (ctx: {p1DataIndex: number}) => string | undefined };
}
interface ChartTitleItem { raw?: {x?: unknown} | null; label?: unknown }
interface ChartLabelContext { dataset: {label?: unknown; _kind?: unknown}; parsed: {y?: unknown}; dataIndex: number }

export {
  closeManualAddFromDetail,
  deleteManualEntryFromDetail,
  openManualAddFromDetail,
  saveManualEntryFromDetail,
};
const WEARABLE_DETAIL_RANGES = [
  { key: '90d', days: 90, label: '90d', coverageSuffix: 'of last 90 days', emptyWindow: 'the last 90 days' },
  { key: '6m', days: 180, label: '6m', coverageSuffix: 'of last 6 months', emptyWindow: 'the last 6 months' },
  { key: '1y', days: 365, label: '1y', coverageSuffix: 'of last 12 months', emptyWindow: 'the last 12 months' },
  { key: 'all', days: null, label: 'All', coverageSuffix: 'all-time', emptyWindow: 'all recorded data' },
];
const WEARABLE_ALL_HISTORY_START_DATE = '1970-01-01';
const WEARABLE_DETAIL_RANGE_KEY = 'wearable-detail-range';

export function wearableActionAttrs(action: unknown, attrs: Record<string, unknown> = {}) {
  return actionAttributes("wearable", action, attrs);
}

function getWearableDetailRange() {
  const stored = localStorage.getItem(WEARABLE_DETAIL_RANGE_KEY);
  if (stored && WEARABLE_DETAIL_RANGES.some(r => r.key === stored)) return stored;
  return '90d';
}

export function setWearableDetailRange(metricId: string, rangeKey: unknown) {
  if (!WEARABLE_DETAIL_RANGES.some(r => r.key === rangeKey)) return;
  localStorage.setItem(WEARABLE_DETAIL_RANGE_KEY, rangeKey as string);
  openWearableDetail(metricId, { fromRangeToggle: true });
}

// Monotonic op token: fast successive clicks on different cards should not
// land mismatched data in the shared detail modal.
let _detailOp = 0;

export async function openWearableDetail(metricId: string, opts: WearableDetailOptions = {}) {
  const op = ++_detailOp;
  const summary = state.importedData?.wearableSummary;
  const normalizedMetricId = metricId === 'bp_diastolic' && summary?.metrics?.bp_systolic
    ? 'bp_systolic'
    : metricId;
  const canon = canonicalMetric(normalizedMetricId);
  const m = summary?.metrics?.[normalizedMetricId];
  if (!canon || !m) {
    showNotification?.('No data for this metric yet — run a sync first', 'info');
    return;
  }

  if (!opts.fromRangeToggle) rememberWearableDetailModalTriggerRuntime();

  const rangeKey = getWearableDetailRange();
  const rangeDef = WEARABLE_DETAIL_RANGES.find(r => r.key === rangeKey) || WEARABLE_DETAIL_RANGES[0]!;
  const profileId = getActiveProfileId();
  const endDate = isoDay();
  let startDate;
  if (rangeDef.days == null) {
    startDate = WEARABLE_ALL_HISTORY_START_DATE;
  } else {
    const start = new Date();
    start.setDate(start.getDate() - rangeDef.days);
    startDate = isoDay(start);
  }

  let rows: Awaited<ReturnType<typeof getDailyRange>> = [];
  let pairedRows: Awaited<ReturnType<typeof getDailyRange>> = [];
  const isBloodPressureDetail = normalizedMetricId === 'bp_systolic';
  const pairedMetricId = isBloodPressureDetail ? 'bp_diastolic' : null;
  const pairedMetric = pairedMetricId ? summary?.metrics?.[pairedMetricId] : null;
  try {
    rows = await getDailyRange(profileId, m.primarySource, startDate, endDate);
    if (pairedMetricId && pairedMetric?.primarySource && pairedMetric.primarySource !== m.primarySource) {
      pairedRows = await getDailyRange(profileId, pairedMetric.primarySource, startDate, endDate);
    } else {
      pairedRows = rows;
    }
  } catch (e) {
    showNotification?.(`Couldn't read local history: ${getErrorMessage(e)}`, 'error', 4000);
    return;
  }
  if (op !== _detailOp) return;

  const series = (rows
    .map(r => ({ date: r.date, v: r[normalizedMetricId] }))
    .filter(p => isMetricValueMeaningful(normalizedMetricId, p.v))
    .sort((a, b) => a.date.localeCompare(b.date))) as WearableSeriesPoint[];
  const pairedSeries = (pairedMetricId ? pairedRows
    .map(r => ({ date: r.date, v: r[pairedMetricId] }))
    .filter(p => isMetricValueMeaningful(pairedMetricId, p.v))
    .sort((a, b) => a.date.localeCompare(b.date)) : []) as WearableSeriesPoint[];

  const allZeroActivity = normalizedMetricId === 'activity_score'
    && series.length > 0
    && series.every(p => p.v === 0);

  let manualRows: Awaited<ReturnType<typeof getDailyRange>> = [];
  if (MANUAL_METRICS.includes(normalizedMetricId)) {
    try {
      manualRows = await getDailyRange(profileId, 'manual', WEARABLE_ALL_HISTORY_START_DATE, endDate);
    } catch {
      manualRows = [];
    }
    if (op !== _detailOp) return;
  }

  const manualEntries = manualRows
    .map(r => ({
      date: r.date,
      v: r[normalizedMetricId],
      pairedV: pairedMetricId ? r[pairedMetricId] : undefined,
      tags: r.tags,
      note: r.note,
    }))
    .filter(p => isMetricValueMeaningful(normalizedMetricId, p.v) || (pairedMetricId && isMetricValueMeaningful(pairedMetricId, p.pairedV)))
    .sort((a, b) => b.date.localeCompare(a.date));
  const manualChartEntries = manualEntries
    .map(p => ({
      ...p,
      v: m.primarySource === 'manual' ? undefined : p.v,
      pairedV: pairedMetric?.primarySource === 'manual' ? undefined : p.pairedV,
    }))
    .filter(p => isMetricValueMeaningful(normalizedMetricId, p.v) || (pairedMetricId && isMetricValueMeaningful(pairedMetricId, p.pairedV)))
    .filter(p => rangeDef.days == null || p.date >= startDate)
    .sort((a, b) => a.date.localeCompare(b.date));
  const chartSampleCount = new Set([
    ...series.map(p => p.date),
    ...pairedSeries.map(p => p.date),
    ...manualChartEntries.map(p => p.date),
  ].filter(Boolean)).size;

  const modal = document.getElementById('detail-modal');
  const overlay = document.getElementById('modal-overlay');
  if (!modal || !overlay) return;

  if (state.chartInstances['modal']) {
    state.chartInstances['modal'].destroy();
    delete state.chartInstances['modal'];
  }

  modal.innerHTML = buildWearableDetailHtml(canon, m, series, normalizedMetricId, manualEntries, {
    allZeroActivity,
    rangeKey,
    rangeStartDate: startDate,
    pairedMetric,
    pairedSeries,
    pairedMetricId,
    chartSampleCount,
    manualChartSampleCount: manualChartEntries.length,
  });
  openModalOverlay(overlay);

  const focusTarget = opts.fromRangeToggle
    ? modal.querySelector('.wearable-detail-range .ctx-btn-option.active')
    : modal.querySelector('.modal-close');
  if (focusTarget instanceof HTMLElement) focusTarget.focus();
  _installWearableModalFocusTrap(modal);

  const canvas = document.getElementById('chart-modal');
  if (canvas && (series.length > 0 || pairedSeries.length > 0 || manualChartEntries.length > 0)) {
    if (canvas instanceof HTMLCanvasElement) {
      if (isBloodPressureDetail) renderBloodPressureChart(canvas, canon, m, series, pairedSeries, manualChartEntries, pairedMetric);
      else renderWearableChart(canvas, canon, m, series, manualChartEntries);
    }
  }
}

let _modalTrapHandler: ((e: KeyboardEvent) => void) | null = null;

export function _uninstallWearableModalFocusTrap() {
  if (_modalTrapHandler) {
    document.removeEventListener('keydown', _modalTrapHandler!, true);
    _modalTrapHandler = null;
  }
}

function _installWearableModalFocusTrap(modal: HTMLElement) {
  _uninstallWearableModalFocusTrap();
  _modalTrapHandler = (e) => {
    if (e.key !== 'Tab') return;
    const overlay = document.getElementById('modal-overlay');
    if (!overlay?.classList?.contains('show')) {
      document.removeEventListener('keydown', _modalTrapHandler!, true);
      _modalTrapHandler = null;
      return;
    }
    const focusable = modal.querySelectorAll<HTMLElement>(
      'button:not([disabled]), a[href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
    );
    if (focusable.length === 0) return;
    const first = focusable[0]!;
    const last = focusable[focusable.length - 1]!;
    const active = document.activeElement;
    if (e.shiftKey && active === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && active === last) {
      e.preventDefault();
      first.focus();
    }
  };
  document.addEventListener('keydown', _modalTrapHandler, true);
}

function buildManualEntriesSection(metricId: string, manualEntries: readonly ManualDetailPoint[], primarySource: unknown) {
  if (!MANUAL_METRICS.includes(metricId)) return '';
  if (manualEntries.length === 0) {
    if (primarySource && primarySource !== 'manual') {
      return renderWearableDetailPresentation("WearableManualEntries", "compactEmpty", {
      addActionAttributes: () => (wearableActionAttrs('open-detail-manual-add', { metric: metricId }))
    });
    }
    return renderWearableDetailPresentation("WearableManualEntries", "empty", {
      addActionAttributes: () => (wearableActionAttrs('open-detail-manual-add', { metric: metricId }))
    });
  }

  const canon = canonicalMetric(metricId);
  const canonicalUnit = canon?.unit || '';
  const unit = wearableDisplayUnit(metricId, canonicalUnit, state.unitSystem);
  const metricLabel = canon?.label || metricId;
  const isBloodPressure = metricId === 'bp_systolic';
  const formatEntryValue = (e: ManualDetailPoint) => {
    if (isBloodPressure) {
      const sys = isMetricValueMeaningful('bp_systolic', e.v)
        ? formatWearableMetricValue(metricId, e.v as number | null | undefined, canonicalUnit, state.unitSystem)
        : '—';
      const dia = isMetricValueMeaningful('bp_diastolic', e.pairedV)
        ? formatWearableMetricValue(metricId, e.pairedV as number | null | undefined, canonicalUnit, state.unitSystem)
        : '—';
      return `${sys}/${dia}`;
    }
    return formatWearableMetricValue(metricId, e.v as number | null | undefined, canonicalUnit, state.unitSystem);
  };
  const formatSpokenDate = (iso: string) => {
    try {
      const d = new Date(iso + 'T00:00:00');
      return d.toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
    } catch {
      return iso;
    }
  };
  const rows = manualEntries.map(e => {
    const tagChips = Array.isArray(e.tags) && e.tags.length
      ? renderWearableDetailPresentation("WearableManualEntries", "tags", {
      tagItems: () => ((e.tags as unknown[]).map(t => renderWearableDetailPresentation("WearableManualEntries", "tag", {
      tag: () => (escapeHTML(t))
    })).join(''))
    })
      : '';
    const noteRow = (typeof e.note === 'string' && e.note.trim())
      ? renderWearableDetailPresentation("WearableManualEntries", "note", {
      note: () => (escapeHTML(e.note))
    })
      : '';
    const valueRead = formatEntryValue(e);
    const ariaText = `Delete ${isBloodPressure ? 'blood pressure' : metricLabel.toLowerCase()} reading from ${formatSpokenDate(e.date)}, ${valueRead}${unit ? ' ' + unit : ''}`;
    return renderWearableDetailPresentation("WearableManualEntries", "row", {
      noteClass: () => (noteRow ? ' has-note' : ''),
      dateAttribute: () => (escapeHTML(e.date)),
      shortDate: () => (escapeHTML(shortDate(e.date))),
      value: () => (valueRead),
      optionalUnit: () => (unit ? renderWearableDetailPresentation("WearableManualEntries", "unit", {
      unit: () => (escapeHTML(unit))
    }) : ''),
      tags: () => (tagChips),
      accessibleDeleteLabel: () => (escapeHTML(ariaText)),
      deleteActionAttributes: () => (wearableActionAttrs('delete-detail-manual-entry', { metric: metricId, date: e.date })),
      note: () => (noteRow)
    });
  }).join('');
  return renderWearableDetailPresentation("WearableManualEntries", "list", {
      entryCount: () => (manualEntries.length),
      addActionAttributes: () => (wearableActionAttrs('open-detail-manual-add', { metric: metricId })),
      rows: () => (rows)
    });
}

function buildWearableDetailHtml(canon: CanonicalWearableMetric, m: DetailMetricReader, series: readonly WearableSeriesPoint[], metricId: string, manualEntries: readonly ManualDetailPoint[] = [], opts: DetailHtmlOptions = {}) {
  const adapter = adapterById(m.primarySource)!;
  const sourceName = adapter?.displayName || m.primarySource;
  const canonicalUnit = canon.unit || '';
  const unit = wearableDisplayUnit(metricId, canonicalUnit, state.unitSystem);
  const unitSpaced = unit ? ' ' + escapeHTML(unit) : '';
  const subLabel = canon.sub ? renderWearableDetailPresentation("WearableDetailChrome", "subLabel", {
      subLabel: () => (escapeHTML(canon.sub))
    }) : '';
  const formatV = (v: unknown) => (formatWearableMetricValue as (metricId: string, value: unknown, canonicalUnit: string, unitSystem: string) => string)(metricId, v, canonicalUnit, state.unitSystem);

  const trendWord = m.trend30d === 'declining' ? 'declining'
                   : m.trend30d === 'rising' ? 'rising'
                   : m.trend30d === 'improving' ? 'improving'
                   : 'flat';

  const suppressDelta = !m.baseline || !isFinite(m.baseline)
                     || metricId === 'steps'
                     || (m.latest === 0 && Math.abs(m.baseline) > 0.5);
  let deltaStr: string | null = null;
  if (!suppressDelta && m.latest != null && isFinite(m.latest)) {
    if (canon?.sub === 'Δ') {
      const diff = m.latest - m.baseline;
      const arrow = diff > 0.005 ? '↑' : diff < -0.005 ? '↓' : '→';
      deltaStr = `${arrow} ${Math.abs(diff).toFixed(2)}${unit}`;
    } else {
      const deltaPct = (m.latest - m.baseline) / m.baseline * 100;
      const arrow = deltaPct > 0.5 ? '↑' : deltaPct < -0.5 ? '↓' : '→';
      deltaStr = `${arrow} ${Math.abs(deltaPct).toFixed(0)}%`;
    }
  }

  const DAY_COMPANION = { hrv_rmssd: 'hrv_day', rhr: 'hr_day' };
  const companionId = (DAY_COMPANION as Record<string, unknown>)[metricId] as string | undefined;
  const companion = companionId ? state.importedData?.wearableSummary?.metrics?.[companionId] : null;
  const companionLabel = metricId === 'hrv_rmssd' ? 'Daytime HRV'
                       : metricId === 'rhr'       ? 'Daytime HR'
                       : null;
  const companionUnitSpaced = companion ? unitSpaced : '';

  const rangeKey = opts.rangeKey || '90d';
  const rangeDef = WEARABLE_DETAIL_RANGES.find(r => r.key === rangeKey) || WEARABLE_DETAIL_RANGES[0]!;
  const rangeStartDate = typeof opts.rangeStartDate === 'string' ? opts.rangeStartDate : WEARABLE_ALL_HISTORY_START_DATE;
  const pairedMetric = (metricId === 'bp_systolic' ? opts.pairedMetric : null) as DetailMetricReader;
  const pairedSeries = Array.isArray(opts.pairedSeries) ? opts.pairedSeries : [];
  const chartSampleCount = Number.isFinite(opts.chartSampleCount)
    ? opts.chartSampleCount
    : Math.max(series.length, pairedSeries.length);
  const pairedUnitSpaced = unitSpaced;
  const formatPaired = (sys: unknown, dia: unknown, includeUnit = true) => {
    const sysText = isMetricValueMeaningful('bp_systolic', sys) ? formatV(sys) : '—';
    const diaText = isMetricValueMeaningful('bp_diastolic', dia) ? formatV(dia) : '—';
    return `${sysText}/${diaText}${includeUnit ? pairedUnitSpaced : ''}`;
  };
  const latestPairedReading = (() => {
    if (!pairedMetric) return null;
    const diastolicByDate = new Map(pairedSeries.map(p => [p.date, p.v]));
    const candidates: Array<{date: string; sys: unknown; dia: unknown}> = [];
    for (const point of series) {
      const dia = diastolicByDate.get(point.date);
      if (isMetricValueMeaningful('bp_systolic', point.v) && isMetricValueMeaningful('bp_diastolic', dia)) {
        candidates.push({ date: point.date, sys: point.v, dia });
      }
    }
    const manualPairedEntries = manualEntries
      .filter(point => rangeDef.days == null || point.date >= rangeStartDate);
    for (const point of manualPairedEntries) {
      if (isMetricValueMeaningful('bp_systolic', point.v) && isMetricValueMeaningful('bp_diastolic', point.pairedV)) {
        candidates.push({ date: point.date, sys: point.v, dia: point.pairedV });
      }
    }
    return candidates.sort((a, b) => b.date.localeCompare(a.date))[0] || null;
  })();
  const latestSummaryDatesMatch = !!(m.latestDate && pairedMetric?.latestDate && m.latestDate === pairedMetric.latestDate);
  const latestSummaryDatesIncomplete = !m.latestDate || !pairedMetric?.latestDate;
  const latestSummaryDatesSplit = !!(m.latestDate && pairedMetric?.latestDate && m.latestDate !== pairedMetric.latestDate);
  const latestBpValue = latestPairedReading
    ? formatPaired(latestPairedReading.sys, latestPairedReading.dia)
    : (latestSummaryDatesMatch ? formatPaired(m.latest, pairedMetric?.latest) : '—');
  const latestBpDate = latestPairedReading
    ? shortDate(latestPairedReading.date)
    : (latestSummaryDatesSplit
        ? `No same-date pair · sys ${shortDate(m.latestDate)} · dia ${shortDate(pairedMetric.latestDate)}`
        : (latestSummaryDatesIncomplete
            ? `No same-date pair${m.latestDate ? ` · sys ${shortDate(m.latestDate)}` : ''}${pairedMetric?.latestDate ? ` · dia ${shortDate(pairedMetric.latestDate)}` : ''}`
            : shortDate(m.latestDate)));
  const baseStats = pairedMetric ? [
    ['Latest',   latestBpValue, latestBpDate],
    ['Baseline (90d)', formatPaired(m.baseline, pairedMetric.baseline), 'median'],
    ['7-day avg', formatPaired(m.rolling?.d7, pairedMetric.rolling?.d7), ''],
    ['30-day avg', formatPaired(m.rolling?.d30, pairedMetric.rolling?.d30), ''],
    ['Typical range', `${formatPaired(m.baselineP25, pairedMetric.baselineP25, false)} – ${formatPaired(m.baselineP75, pairedMetric.baselineP75, false)}${pairedUnitSpaced}`, '25th–75th percentile'],
    ['Chart samples', `${chartSampleCount}d`, rangeDef.coverageSuffix],
  ] : [
    ['Latest',   `${formatV(m.latest)}${unitSpaced}`, m.latestDate ? shortDate(m.latestDate) : ''],
    ['Baseline (90d)', `${formatV(m.baseline)}${unitSpaced}`, 'median'],
    ['7-day avg', `${formatV(m.rolling?.d7)}${unitSpaced}`, ''],
    ['30-day avg', `${formatV(m.rolling?.d30)}${unitSpaced}`, ''],
    ['Typical range', `${formatV(m.baselineP25)} – ${formatV(m.baselineP75)}${unitSpaced}`, '25th–75th percentile'],
    ['Chart samples', `${series.length}d`, rangeDef.coverageSuffix],
  ];

  if (companion && companionLabel && typeof companion.latest === 'number') {
    baseStats.push([
      `${companionLabel} (latest)`,
      `${formatV(companion.latest)}${companionUnitSpaced}`,
      companion.latestDate ? `daytime · ${shortDate(companion.latestDate)}` : 'daytime',
    ]);
    if (typeof companion.rolling?.d7 === 'number') {
      baseStats.push([
        `${companionLabel} (7d)`,
        `${formatV(companion.rolling.d7)}${companionUnitSpaced}`,
        'daytime · 7-day avg',
      ]);
    }
    if (typeof companion.rolling?.d30 === 'number' && companion.weekly && companion.weekly.length >= 2) {
      baseStats.push([
        `${companionLabel} (30d)`,
        `${formatV(companion.rolling.d30)}${companionUnitSpaced}`,
        'daytime · 30-day avg',
      ]);
    }
  } else if (companionLabel) {
    const primary = m.primarySource;
    const adapter2 = adapterById(primary);
    const sourceDisplay = adapter2?.displayName || primary || 'this source';
    const tooltip = (() => {
      if (metricId === 'hrv_rmssd') {
        if (primary === 'oura' || primary === 'whoop') {
          return `${sourceDisplay} v2 API exposes overnight HRV only. To see daytime HRV, connect Apple Health, Fitbit, or Polar (workout-tracked HRV).`;
        }
        if (primary === 'polar') return 'Polar surfaces daytime HRV from recorded workouts only — no exercise transactions in the last 90 days.';
        return 'No daytime HRV samples in the last 90 days. Apple Health and Fitbit (dailyRmssd) typically populate this.';
      }
      return 'No daytime heart-rate samples in the last 90 days. Re-sync the connected wearable.';
    })();
    baseStats.push([
      companionLabel,
      '—',
      `Not from ${sourceDisplay} · why?`,
      tooltip,
    ]);
  }

  const statsCells = baseStats.map(([label, val, sub, tooltip]) => renderWearableDetailPresentation("WearableDetailStats", "stat", {
      optionalTooltipAttributes: () => (tooltip ? ` title="${escapeHTML(tooltip)}"` : ''),
      label: () => (escapeHTML(label)),
      value: () => (val),
      optionalSubLabel: () => (sub ? renderWearableDetailPresentation("WearableDetailStats", "subLabel", {
      subLabel: () => (escapeHTML(sub))
    }) : '')
    })).join('');

  const hasManualChartSamples = Number(opts.manualChartSampleCount || 0) > 0;
  const emptyHint = opts.allZeroActivity
    ? renderWearableDetailPresentation("WearableDetailFeedback", "zeroActivity", {

    })
    : series.length === 0 && pairedSeries.length === 0 && !hasManualChartSamples
      ? manualEntries.length > 0
        ? renderWearableDetailPresentation("WearableDetailFeedback", "emptyChartWithManual", {
      emptyWindow: () => (escapeHTML(rangeDef.emptyWindow)),
      olderManualHint: () => (m.primarySource === 'manual' && rangeDef.days != null ? '; switch to All to chart older manual readings' : '')
    })
        : renderWearableDetailPresentation("WearableDetailFeedback", "emptyChart", {
      emptyWindow: () => (escapeHTML(rangeDef.emptyWindow))
    })
      : '';

  const connectedSources = state.importedData?.wearableSummary?.sources || {};
  const showSwapButton = Object.keys(connectedSources).length > 1 && !!adapter;
  const swapButton = showSwapButton
    ? pairedMetric
      ? (() => {
          const pairedAdapter = adapterById(pairedMetric.primarySource);
          const pairedSourceName = pairedAdapter?.displayName || pairedMetric.primarySource || 'Diastolic source';
          return renderWearableDetailPresentation("WearableDetailChrome", "pairedSourceSwap", {
      systolicActionAttributes: () => (wearableActionAttrs('choose-source', { metric: 'bp_systolic' })),
      systolicSource: () => (escapeHTML(sourceName)),
      diastolicActionAttributes: () => (wearableActionAttrs('choose-source', { metric: 'bp_diastolic' })),
      diastolicSource: () => (escapeHTML(pairedSourceName))
    });
        })()
      : renderWearableDetailPresentation("WearableDetailChrome", "sourceSwap", {
      sourceActionAttributes: () => (wearableActionAttrs('choose-source', { metric: metricId })),
      sourceName: () => (escapeHTML(adapter.displayName))
    })
    : '';

  const emfSleepHint = _buildEMFSleepHint(metricId, m);
  const rangePills = WEARABLE_DETAIL_RANGES.map(r =>
    renderWearableDetailPresentation("WearableDetailChrome", "rangePill", {
      activeClass: () => (r.key === rangeKey ? ' active' : ''),
      pressed: () => (r.key === rangeKey),
      rangeActionAttributes: () => (wearableActionAttrs('set-detail-range', { metric: metricId, range: r.key })),
      label: () => (escapeHTML(r.label))
    })
  ).join('');

  return renderWearableDetailPresentation("WearableDetailChrome", "modal", {
      closeActionAttributes: () => (wearableActionAttrs('modal-close')),
      label: () => (escapeHTML(canon.label)),
      subLabel: () => (subLabel),
      sourceName: () => (escapeHTML(sourceName)),
      optionalDelta: () => (deltaStr ? ` · ${deltaStr} vs baseline` : ''),
      trend: () => (escapeHTML(trendWord)),
      sourceSwap: () => (swapButton),
      rangePills: () => (rangePills),
      emptyHint: () => (emptyHint),
      stats: () => (statsCells),
      manualEntries: () => (buildManualEntriesSection(metricId, manualEntries, m.primarySource)),
      emfHint: () => (emfSleepHint)
    });
}

function _buildEMFSleepHint(metricId: string, m: DetailMetricReader) {
  const SLEEP_METRICS = new Set(['sleep_score', 'sleep_efficiency', 'hrv_rmssd']);
  if (!SLEEP_METRICS.has(metricId)) return '';
  const sources = state.importedData?.wearableSummary?.sources;
  if (!sources || Object.keys(sources).length === 0) return '';
  const d7 = m?.rolling?.d7;
  const baseline = m?.baseline;
  const p25 = m?.baselineP25;
  if (typeof d7 !== 'number' || typeof baseline !== 'number') return '';
  const regressing = d7 < baseline && (typeof p25 !== 'number' || d7 < p25);
  if (!regressing) return '';
  const assessments = state.importedData?.emfAssessment?.assessments || [];
  if (assessments.length) {
    const latest = assessments.reduce((a: {date: string}, b: {date: string}) => (a.date > b.date ? a : b));
    const ageDays = (Date.now() - new Date(latest.date + 'T00:00:00').getTime()) / 86400000;
    if (ageDays < 120) return '';
  }
  return renderWearableDetailPresentation("WearableDetailFeedback", "emfHint", {
      assessmentActionAttributes: () => (wearableActionAttrs('open-emf-assessment'))
    });
}

function renderWearableChart(canvas: HTMLCanvasElement, canon: CanonicalWearableMetric, m: DetailMetricReader, series: readonly WearableSeriesPoint[], manualSeries: readonly ManualDetailPoint[] = []) {
  if (!hasWearableDetailChartRuntime() || !isChartDateAdapterReady()) {
    ensureChartJs().then(() => {
      const currentCanvas = document.getElementById(canvas.id);
      if (currentCanvas) renderWearableChart(currentCanvas as HTMLCanvasElement, canon, m, series, manualSeries);
    }).catch(() => {});
    return;
  }
  const tc = getChartColors();
  const primaryData = series.map(p => ({ x: p.date, y: p.v }));
  const manualData = manualSeries.map(p => ({ x: p.date, y: p.v }));
  const xDates = [...series.map(p => p.date), ...manualSeries.map(p => p.date)].sort();
  const values = [...series.map(p => p.v), ...manualSeries.map(p => p.v)];
  if (values.length === 0) return;
  const hasManualOverlay = primaryData.length > 0 && manualData.length > 0;
  const baselineIsFinite = typeof m.baseline === 'number' && isFinite(m.baseline);
  const baselineValues = baselineIsFinite && xDates.length
    ? [{ x: xDates[0], y: m.baseline }, { x: xDates[xDates.length - 1], y: m.baseline }]
    : [];
  const isCumulative = CUMULATIVE_METRICS.has(canon.id);
  const todayISO = isoDay();
  const isPartialIdx = (idx: number) => isCumulative && series[idx]?.date === todayISO;
  const partialColor = '#f59e0b';
  const primaryAdapter = adapterById(m.primarySource);
  const primaryLabel = primaryAdapter?.displayName || canon.label;

  const yValues = baselineIsFinite ? [...values, m.baseline] : values;
  const ymin = Math.min(...(yValues as number[]));
  const ymax = Math.max(...(yValues as number[]));
  const pad = Math.max((ymax - ymin) * 0.08, 0.5);

  const canonicalUnit = canon.unit || '';
  const unit = wearableDisplayUnit(canon.id, canonicalUnit, state.unitSystem);
  const formatV = (v: unknown) => (formatWearableMetricValue as (metricId: string, value: unknown, canonicalUnit: string, unitSystem: string) => string)(canon.id, v, canonicalUnit, state.unitSystem);
  const titleForPoint = (items: readonly ChartTitleItem[] | null | undefined) => {
    const rawX = items?.[0]?.raw?.x;
    if (typeof rawX === 'string') return shortDate(rawX);
    return items?.[0]?.label || '';
  };
  const datasets: WearableChartDataset[] = [];
  if (primaryData.length > 0) {
    datasets.push({
      label: primaryLabel,
      data: primaryData,
      _kind: 'primary',
      borderColor: tc.lineColor || '#60a5fa',
      backgroundColor: 'transparent',
      borderWidth: 2,
      pointRadius: primaryData.map((_, i) => isPartialIdx(i) ? 5 : 0),
      pointBackgroundColor: primaryData.map((_, i) => isPartialIdx(i) ? partialColor : 'transparent'),
      pointBorderColor: primaryData.map((_, i) => isPartialIdx(i) ? partialColor : 'transparent'),
      pointHoverRadius: primaryData.map((_, i) => isPartialIdx(i) ? 7 : 4),
      tension: 0.3,
      spanGaps: true,
      segment: {
        borderDash: (ctx) => isPartialIdx(ctx.p1DataIndex) ? [5, 4] : undefined,
        borderColor: (ctx) => isPartialIdx(ctx.p1DataIndex) ? partialColor : undefined,
      },
    });
  }
  if (baselineValues.length > 0) {
    datasets.push({
      label: 'Baseline',
      data: baselineValues,
      _kind: 'baseline',
      borderColor: tc.gridColor || '#9ca3af',
      backgroundColor: 'transparent',
      borderWidth: 1,
      borderDash: [4, 4],
      pointRadius: 0,
      pointHoverRadius: 0,
      tension: 0,
    });
  }
  if (manualData.length > 0) {
    datasets.push({
      type: 'scatter',
      label: 'Manual',
      data: manualData,
      _kind: 'manual',
      borderColor: partialColor,
      backgroundColor: partialColor,
      pointRadius: 5,
      pointHoverRadius: 7,
      showLine: false,
    });
  }

  const chart = createWearableDetailChartRuntime(canvas, {
    type: 'line',
    data: { datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: hasManualOverlay ? 'nearest' : 'index', intersect: false, axis: 'x' },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: tc.tooltipBg, titleColor: tc.tooltipTitle,
          bodyColor: tc.tooltipBody, borderColor: tc.tooltipBorder, borderWidth: 1,
          callbacks: {
            title: titleForPoint,
            label: (c: ChartLabelContext) => {
              const base = `${c.dataset.label}: ${formatV(c.parsed.y)}${unit ? ' ' + unit : ''}`;
              if (c.dataset._kind === 'manual') return `${base}  (manual entry)`;
              return (c.dataset._kind === 'primary' && isPartialIdx(c.dataIndex))
                ? `${base}  (partial day · in progress)`
                : base;
            },
          },
        },
      },
      scales: {
        x: {
          type: 'time',
          time: { tooltipFormat: 'MMM d, yyyy', displayFormats: { day: 'MMM d', month: 'MMM yyyy' } },
          ticks: { source: 'auto', color: tc.tickColor, font: { size: 10 }, maxTicksLimit: 8 },
          grid: { display: false },
        },
        y: {
          min: ymin - pad, max: ymax + pad,
          ticks: {
            color: tc.tickColor,
            font: { size: 10 },
            callback: canon.id === 'weight'
              ? (value: unknown) => formatV(Number(value))
              : formatChartTickValue,
          },
          grid: { color: tc.gridColor },
        },
      },
    },
  });
  if (chart) state.chartInstances['modal'] = chart;
}

configureWearableManualDetailDeps({
  closeDetail: closeWearableDetailModalRuntime,
  openDetail: openWearableDetail,
});
